import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  Num,
  Pairs,
  Select,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['WITHHOLDING_STATUS', '원천징수이행상황신고서'],
  ['TUITION_REPAYMENT', '학자금상환 신고서'],
  ['LOCAL_INCOME_TAX', '법인지방소득세'],
  ['RESIDENT_TAX_EMPLOYEE', '주민세(종업원분) 신고서'],
  ['SIMPLIFIED_PAYMENT', '간이지급명세서'],
  ['SUBMISSION_SUMMARY', '제출집계표'],
  ['PAYMENT_MEDIA', '지급명세 전산매체'],
];

function typeName(value: unknown): string {
  const found = TYPE_OPTIONS.find((o) => o[0] === value);
  return found ? found[1] : String(value ?? '');
}

export default function FnSfr02303Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [filingType, setFilingType] = useState('');
  const [month, setMonth] = useState('');
  const [target, setTarget] = useState<Row | null>(null);
  const [result, setResult] = useState<Row | null>(null);

  const openCreate = () => {
    setFilingType('');
    setMonth('');
    setCreating(true);
  };

  const create = async () => {
    if (!filingType) throw new Error('신고서 유형을 선택해 주세요.');
    if (!/^\d{6}$/.test(month)) throw new Error('귀속연월은 YYYYMM 형식으로 입력해 주세요.');
    const created = await call('POST', '/tax-filings/generate-local', role, { filingType, attributionMonth: month });
    setRows([created, ...rows]);
    setCreating(false);
    notify('신고서를 작성했습니다.');
  };

  const submit = async () => {
    if (!target) return;
    const id = target['taxFilingId'];
    const done = await call('POST', '/tax-filings/' + String(id) + '/submit', role);
    setRows(rows.map((r) => (r['taxFilingId'] === id ? { ...r, filingStatus: done['filingStatus'] } : r)));
    setResult(done);
    setTarget(null);
    notify('전자신고를 완료했습니다.');
  };

  return (
    <div>
      <h1>지방세 전자신고</h1>
      <Band total={rows.length}>
        <button onClick={openCreate}>신고서 작성</button>
      </Band>
      <DataTable
        rows={rows}
        empty="아직 작성한 신고서가 없습니다. 신고서 작성 버튼으로 시작해 주세요."
        columns={[
          { key: 'filingType', label: '신고서 유형', render: (r) => typeName(r['filingType']) },
          { key: 'attributionMonth', label: '귀속연월' },
          { key: 'totalAmount', label: '집계 금액', render: (r) => <Num value={r['totalAmount']} /> },
          { key: 'filingStatus', label: '신고 상태', render: (r) => <Badge value={r['filingStatus']} /> },
          {
            key: 'action',
            label: '처리',
            render: (r) =>
              r['filingStatus'] === 'DRAFT' ? (
                <button className="ghost" onClick={() => setTarget(r)}>
                  전자신고
                </button>
              ) : null,
          },
        ]}
      />
      {result && (
        <div className="doc">
          <section className="box">
            <h2>전자신고 결과</h2>
            <Pairs
              items={[
                ['신고 상태', <Badge value={result['filingStatus']} />],
                ['전자신고 일시', String(result['filedAt'] ?? '')],
                ['접수번호', String(result['receiptNumber'] ?? '')],
                ['전자신고 결과 메시지', String(result['resultMessage'] ?? '')],
                ['생성된 국세청 전자파일 이름', String(result['electronicFileName'] ?? '')],
              ]}
            />
          </section>
        </div>
      )}
      {creating && (
        <Drawer title="신고서 작성" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="작성">
            <Field label="신고서 유형" required>
              <Select value={filingType} onChange={setFilingType} options={TYPE_OPTIONS} />
            </Field>
            <Field label="귀속연월" required hint="YYYYMM 형식 (예: 202405)">
              <TextInput value={month} onChange={setMonth} />
            </Field>
          </Form>
        </Drawer>
      )}
      {target && (
        <Drawer title="전자신고" onClose={() => setTarget(null)}>
          <Form
            onSubmit={submit}
            submit="전자신고 요청"
            note="전자신고를 요청하면 국세청으로 전자파일이 전송되고 접수 결과가 신고서에 기록됩니다."
          >
            <Pairs
              items={[
                ['신고서 유형', typeName(target['filingType'])],
                ['귀속연월', String(target['attributionMonth'] ?? '')],
              ]}
            />
          </Form>
        </Drawer>
      )}
    </div>
  );
}
